window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cb35bd03884a4b57"]={"versions": [{"id": "FIG-cb35bd03884a4b57", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Mcu_PerformReset</code>) zur Darstellung des synchronen Funktionsaufrufs für das Durchführen eines Hardware-Resets innerhalb des AUTOSAR MCU-Treibers (Microcontroller Unit Driver, Microcontroller Abstraction Layer / MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Generic Elements::User</strong>: Aufrufende Entität / Software-Komponente oberhalb oder außerhalb des Treibers.\n</li><li><strong>Mcu::Mcu</strong>: Instanz des AUTOSAR MCU-Treibers mit Subsystem-/Dekompositionssymbol.\n</li><li><strong>Mcu_PerformReset()</strong>: Synchrone Service-Schnittstelle des MCU-Treibers.\n</li><li><strong>Hardware reset</strong>: Lokale interne Hardware-Operation / Selbstaufruf des MCU-Treibers.\n</li><li><strong>Mcu_PerformReset</strong>: Synchrone Rückkehrnachricht (Return Message) an den Aufrufer.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Entität <code>Generic Elements::User</code> ruft synchron die Operation <code>Mcu_PerformReset()</code> auf der Lebenslinie <code>Mcu::Mcu</code> auf.\n</li><li>An der MCU-Lebenslinie wird ein Aktivierungsbalken geöffnet. Ein angehefteter Notizkommentar spezifiziert: „The function is performed synchronously“.\n</li><li>Der MCU-Treiber triggert über einen internen Selbstaufruf <code>Hardware reset</code> das Auslösen des Hardware-Resets.\n</li><li>Nach Ausführung der Reset-Aktion kehrt der Kontrollfluss über die gestrichelte Rückkehrnachricht <code>Mcu_PerformReset</code> zur aufrufenden Entität <code>Generic Elements::User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktion <code>Mcu_PerformReset()</code> ist synchron definiert. Da ein Hardware-Reset üblicherweise die Ausführung der MCU unmittelbar abbricht oder neu startet, zeigt das Sequenzdiagramm formal die Rückkehr des Kontrollflusses, sofern die Hardware den Befehl synchron quittiert oder der Reset verzögert greift. Integratoren müssen beachten, dass nach Initiierung des Resets keine weiteren regulären MCU-Zustände garantiert sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-75650b78f19fe149", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Mcu_PerformReset</code>) zur Darstellung des synchronen Funktionsaufrufs für das Durchführen eines Hardware-Resets innerhalb des AUTOSAR MCU-Treibers (Microcontroller Unit Driver, Microcontroller Abstraction Layer / MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Generic Elements::User</strong>: Aufrufende Entität / Software-Komponente oberhalb des Treibers.\n</li><li><strong>«module» Mcu::Mcu</strong>: Instanz des AUTOSAR MCU-Treibers, typisiert als Modul mit Dekompositionssymbol.\n</li><li><strong>Mcu_PerformReset()</strong>: Synchrone Service-Schnittstelle des MCU-Treibers.\n</li><li><strong>Hardware reset</strong>: Lokale interne Hardware-Operation / Selbstaufruf des MCU-Treibers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Entität <code>Generic Elements::User</code> ruft die Funktion <code>Mcu_PerformReset()</code> auf der Lebenslinie von <code>«module» Mcu::Mcu</code> auf.\n</li><li>An der Lebenslinie des MCU-Treibers wird ein Ausführungsbalken aktiviert. Eine Notiz beschreibt: „The function is performed synchronously“.\n</li><li>Das Modul führt über einen internen Selbstaufruf <code>Hardware reset</code> den eigentlichen Hardware-Reset durch.\n</li><li>Es existiert keine Rückkehrnachricht (Return Message); der Kontrollfluss kehrt nicht zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung von <code>Mcu_PerformReset()</code> führt direkt zur Auslösung des Hardware-Resets ohne Rückkehr zum Aufrufer (keine Rücksprungnachricht). Anwendungsentwickler müssen sicherstellen, dass vor dem Aufruf alle flüchtigen Daten gesichert und abhängige Module in einen sicheren Zustand überführt wurden, da die normale Programmausführung an der Aufrufstelle terminiert. Eine Notiz dokumentiert den Status: „Proposed by TO as per Mcu SWS 1.2.2“.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-79cc237b70914f6e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Mcu_PerformReset</code>) zur Darstellung des synchronen Funktionsaufrufs für das Durchführen eines Hardware-Resets innerhalb des AUTOSAR MCU-Treibers (Microcontroller Unit Driver, Microcontroller Abstraction Layer / MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>User «module»</strong>: Aufrufendes Software-Modul.\n</li><li><strong>«module» Mcu</strong>: MCU-Treibermodul mit Dekompositionssymbol.\n</li><li><strong>Mcu_PerformReset()</strong>: Synchrone Service-Schnittstelle des MCU-Treibers.\n</li><li><strong>Hardware reset()</strong>: Lokale Hardware-Funktion / interner Selbstaufruf des MCU-Treibers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>User</code> ruft synchron die Funktion <code>Mcu_PerformReset()</code> auf der Lebenslinie von <code>«module» Mcu</code> auf.\n</li><li>Der MCU-Treiber aktiviert seinen Ausführungsfokus. Eine Notiz besagt: „The function is performed synchronously“.\n</li><li>Das Modul initiiert über den internen Aufruf <code>Hardware reset()</code> den Hardware-Reset.\n</li><li>Ein Rücksprung zum Aufrufer erfolgt nicht.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung von <code>Mcu_PerformReset()</code> führt direkt zur Auslösung des Hardware-Resets ohne Rückkehr zum Aufrufer (keine Rücksprungnachricht). Anwendungsentwickler müssen sicherstellen, dass vor dem Aufruf alle flüchtigen Daten gesichert und abhängige Module in einen sicheren Zustand überführt wurden, da die normale Programmausführung an der Aufrufstelle terminiert. Eine Notiz dokumentiert den Status: „Proposed by TO as per Mcu SWS 1.2.2“.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cb35bd03884a4b57", "to": "FIG-75650b78f19fe149", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Return-Nachricht</strong>: Die gestrichelte Rückkehrnachricht <code>Mcu_PerformReset</code> vom Mcu-Modul zum User entfällt vollständig.\n</li><li><strong>Stereotyp</strong>: An der Instanzbox <code>Mcu::Mcu</code> ist das Stereotyp <code>«module»</code> ergänzt.\n</li><li><strong>Metadaten-Kommentar</strong>: Unten ist ein Notizblock mit den Feldern <code>Status: Proposed by TO as per Mcu SWS 1.2.2</code>, <code>Description:</code> und <code>Comments:</code> ergänzt.\n</li></ul>"}, {"from": "FIG-75650b78f19fe149", "to": "FIG-79cc237b70914f6e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Lebenslinie User</strong>: Der Bezeichner <code>Generic Elements::User</code> ist zu <code>User</code> vereinfacht; das Stereotyp <code>«module»</code> ist innerhalb des Lifeline-Headers unterhalb von <code>User</code> platziert.\n</li><li><strong>Lebenslinie Mcu</strong>: Der Bezeichner <code>Mcu::Mcu</code> ist zu <code>Mcu</code> vereinfacht.\n</li><li><strong>Selbstaufruf</strong>: Die Nachricht <code>Hardware reset</code> ist mit Klammern als Methodenaufruf <code>Hardware reset()</code> notiert.\n</li></ul>"}]};
